"""Narrative synthesis via Claude CLI proxy.

Static parser+aggregator give us deterministic data: phase boundaries, metrics, file paths,
slash command names, human interventions. Claude CLI fills the qualitative parts: a session
title, per-phase generic-vs-specific narrative, "what was known/unknown/revealed", and an
end-cap recommendation.

Falls back gracefully when `claude` is not on PATH — emits empty narratives so the
template still renders with deterministic data only.
"""

from __future__ import annotations

import json
import shutil
import subprocess
from dataclasses import dataclass, field

from harness.analyse.aggregator import Phase, SessionAnalysis


@dataclass
class PhaseNarrative:
    generic_purpose: str = ""
    specific_run: str = ""
    known: str = ""
    unknown: str = ""
    reveals: str = ""
    intervention_resp: str = ""  # one-line interpretation of human-in-loop, when present


@dataclass
class Narrative:
    one_line_summary: str = ""
    end_cap_title: str = "Session complete"
    end_cap_body: str = ""
    pattern_worth_keeping: str = ""
    phases: list[PhaseNarrative] = field(default_factory=list)


_PROMPT = """\
You are summarising a Claude Code session for a timeline report. The data is structured —
just provide narrative for the parts that need human reading.

Return STRICT JSON matching this schema:

{
  "one_line_summary": "string, ≤180 chars",
  "end_cap_title": "string, ≤60 chars",
  "end_cap_body": "string, 2–4 sentences describing the final state",
  "pattern_worth_keeping": "string, 1–2 sentences naming a takeaway pattern",
  "phases": [
    {
      "generic_purpose": "string, 1–3 sentences — what this surface generally does",
      "specific_run": "string, 1–3 sentences — what this run actually did",
      "known": "string, ≤120 chars — what was known going in",
      "unknown": "string, ≤120 chars — what was unknown going in",
      "reveals": "string, ≤120 chars — what the phase reveals or unblocks",
      "intervention_resp": "string, ≤200 chars — interpretation of human interventions, or empty if none"
    },
    ... one entry per phase, in order
  ]
}

Do NOT add fields. Do NOT wrap in markdown fences. Return JSON only.

Session context:
"""


def synthesise(analysis: SessionAnalysis, *, model: str = "sonnet") -> Narrative:
    """Call Claude CLI to generate narrative; fall back to empty when unavailable."""
    cli = shutil.which("claude")
    if not cli:
        return _empty_narrative(len(analysis.phases))

    prompt = _build_prompt(analysis)
    try:
        out = subprocess.run(
            [cli, "--print", "--model", model, "--output-format", "text"],
            input=prompt, capture_output=True, text=True, timeout=120,
        )
    except subprocess.TimeoutExpired:
        return _empty_narrative(len(analysis.phases))

    if out.returncode != 0 or not out.stdout.strip():
        return _empty_narrative(len(analysis.phases))

    raw = out.stdout.strip()
    # Strip code fences if model adds them despite instructions
    if raw.startswith("```"):
        lines = raw.splitlines()
        raw = "\n".join(lines[1:-1] if lines[-1].startswith("```") else lines[1:])
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return _empty_narrative(len(analysis.phases))

    return _narrative_from_dict(data, len(analysis.phases))


def _build_prompt(analysis: SessionAnalysis) -> str:
    summary = {
        "session_id": analysis.session.session_id,
        "title": analysis.session.title,
        "duration_seconds": analysis.session.duration_seconds,
        "git_branch": analysis.session.git_branch,
        "cwd": analysis.session.cwd,
        "phases": [_phase_summary(ph) for ph in analysis.phases],
        "totals": {
            "tools": dict(analysis.total_metrics.tool_counts),
            "subagents": dict(analysis.total_metrics.subagent_calls),
            "mcp": dict(analysis.total_metrics.mcp_calls),
            "input_tokens": analysis.total_metrics.input_tokens,
            "output_tokens": analysis.total_metrics.output_tokens,
            "cache_create_tokens": analysis.total_metrics.cache_create_tokens,
            "cache_read_tokens": analysis.total_metrics.cache_read_tokens,
            "cost_usd": analysis.total_cost_usd,
        },
    }
    return _PROMPT + json.dumps(summary, indent=2, default=str)


def _phase_summary(ph: Phase) -> dict:
    interventions = [
        {"timestamp": str(h.timestamp), "text": h.text[:300]}
        for h in ph.interventions
    ]
    # First user prompt body (truncated), to seed the narrative
    first_user_text = ""
    for t in ph.turns:
        if t.role == "user" and t.text:
            first_user_text = t.text[:600]
            break
    return {
        "index": ph.index,
        "title": ph.title,
        "slash_command": ph.slash_command,
        "start": str(ph.start),
        "end": str(ph.end),
        "duration_seconds": ph.duration_seconds,
        "turn_count": len(ph.turns),
        "first_user_text": first_user_text,
        "interventions": interventions,
        "metrics": {
            "tools": dict(ph.metrics.tool_counts),
            "subagents": dict(ph.metrics.subagent_calls),
            "mcp": dict(ph.metrics.mcp_calls),
            "files_written": ph.metrics.files_written[:20],
            "files_edited": ph.metrics.files_edited[:20],
            "files_read": ph.metrics.files_read[:20],
            "bash_commands": ph.metrics.bash_commands,
        },
    }


def _empty_narrative(n_phases: int) -> Narrative:
    return Narrative(
        phases=[PhaseNarrative() for _ in range(n_phases)],
        one_line_summary="Narrative skipped (claude CLI unavailable).",
        end_cap_title="Session complete",
        end_cap_body="Static metrics only; install Claude Code CLI for narrative synthesis.",
    )


def _narrative_from_dict(data: dict, expected_phases: int) -> Narrative:
    phases_list = data.get("phases") or []
    phases = [
        PhaseNarrative(
            generic_purpose=str(p.get("generic_purpose", ""))[:600],
            specific_run=str(p.get("specific_run", ""))[:600],
            known=str(p.get("known", ""))[:200],
            unknown=str(p.get("unknown", ""))[:200],
            reveals=str(p.get("reveals", ""))[:200],
            intervention_resp=str(p.get("intervention_resp", ""))[:300],
        )
        for p in phases_list
    ]
    while len(phases) < expected_phases:
        phases.append(PhaseNarrative())
    phases = phases[:expected_phases]
    return Narrative(
        one_line_summary=str(data.get("one_line_summary", ""))[:300],
        end_cap_title=str(data.get("end_cap_title", "Session complete"))[:80],
        end_cap_body=str(data.get("end_cap_body", ""))[:800],
        pattern_worth_keeping=str(data.get("pattern_worth_keeping", ""))[:400],
        phases=phases,
    )
